def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    frame = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]
    r0, r1 = min(r for r, c in frame), max(r for r, c in frame)
    c0, c1 = min(c for r, c in frame), max(c for r, c in frame)

    row_split = (r0 + r1 + 1) // 2
    col_split = (c0 + c1 + 1) // 2

    for r in range(r0 + 1, r1):
        for c in range(c0 + 1, c1):
            top = r < row_split
            left = c < col_split
            for mr in range(h):
                for mc in range(w):
                    color = grid[mr][mc]
                    if color in (0, 5):
                        continue
                    marker_top = mr < r0
                    marker_left = mc < c0
                    if (top, left) in (
                        (marker_top, marker_left),
                        (not marker_top, not marker_left),
                    ):
                        out[r][c] = color
                        break
                else:
                    continue
                break
    return out
